 		return 0;

 	ret = -EINVAL;

 	if (sizeof(*header) >= firmware->size) {
 		ret = -EOVERFLOW;
 		goto out_fw;
 	}

 	header = (void *)&firmware->data[0];

 	if (memcmp(&header->magic[0], "WMFW", 4) != 0) {
 		cs_dsp_err(dsp, "%s: invalid magic\n", file);
 		goto out_fw;
 	}

 	if (!dsp->ops->validate_version(dsp, header->ver)) {
