 			text = kzalloc(le32_to_cpu(region->len) + 1,
 				       GFP_KERNEL);
 			break;
 		case WMFW_ABSOLUTE:
 			region_name = "Absolute";
 			reg = offset;
 			break;
 		case WMFW_ADSP1_PM:
 		case WMFW_ADSP1_DM:
 		case WMFW_ADSP2_XM:
 		case WMFW_ADSP2_YM:
 		case WMFW_ADSP1_ZM:
 		case WMFW_HALO_PM_PACKED:
 		case WMFW_HALO_XM_PACKED:
