diff --git a/drivers/phy/rockchip/phy-rockchip-inno-usb2.c b/drivers/phy/rockchip/phy-rockchip-inno-usb2.c
index e5efae7b013..8f4c08e599a 100644
--- a/drivers/phy/rockchip/phy-rockchip-inno-usb2.c
+++ b/drivers/phy/rockchip/phy-rockchip-inno-usb2.c
@@ -1341,167 +1341,167 @@ static int rockchip_usb2phy_otg_port_init(struct rockchip_usb2phy *rphy,
 static int rockchip_usb2phy_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct device_node *np = dev->of_node;
 	struct device_node *child_np;
 	struct phy_provider *provider;
 	struct rockchip_usb2phy *rphy;
 	const struct rockchip_usb2phy_cfg *phy_cfgs;
 	unsigned int reg;
 	int index = 0, ret;

 	rphy = devm_kzalloc(dev, sizeof(*rphy), GFP_KERNEL);
 	if (!rphy)
 		return -ENOMEM;

 	if (!dev->parent || !dev->parent->of_node) {
 		rphy->grf = syscon_regmap_lookup_by_phandle(np, "rockchip,usbgrf");
 		if (IS_ERR(rphy->grf)) {
 			dev_err(dev, "failed to locate usbgrf\n");
 			return PTR_ERR(rphy->grf);
 		}
 	} else {
 		rphy->grf = syscon_node_to_regmap(dev->parent->of_node);
 		if (IS_ERR(rphy->grf))
 			return PTR_ERR(rphy->grf);
 	}

 	if (of_device_is_compatible(np, "rockchip,rv1108-usb2phy")) {
 		rphy->usbgrf =
 			syscon_regmap_lookup_by_phandle(dev->of_node,
 							"rockchip,usbgrf");
 		if (IS_ERR(rphy->usbgrf))
 			return PTR_ERR(rphy->usbgrf);
 	} else {
 		rphy->usbgrf = NULL;
 	}

 	if (of_property_read_u32_index(np, "reg", 0, &reg)) {
 		dev_err(dev, "the reg property is not assigned in %pOFn node\n", np);
 		return -EINVAL;
 	}

 	/* support address_cells=2 */
 	if (of_property_count_u32_elems(np, "reg") > 2 && reg == 0) {
 		if (of_property_read_u32_index(np, "reg", 1, &reg)) {
 			dev_err(dev, "the reg property is not assigned in %pOFn node\n", np);
 			return -EINVAL;
 		}
 	}

 	rphy->dev = dev;
 	phy_cfgs = device_get_match_data(dev);
 	rphy->chg_state = USB_CHG_STATE_UNDEFINED;
 	rphy->chg_type = POWER_SUPPLY_TYPE_UNKNOWN;
 	rphy->irq = platform_get_irq_optional(pdev, 0);
 	platform_set_drvdata(pdev, rphy);

 	if (!phy_cfgs)
 		return dev_err_probe(dev, -EINVAL, "phy configs are not assigned!\n");

 	ret = rockchip_usb2phy_extcon_register(rphy);
 	if (ret)
 		return ret;

 	/* find a proper config that can be matched with the DT */
 	do {
 		if (phy_cfgs[index].reg == reg) {
 			rphy->phy_cfg = &phy_cfgs[index];
 			break;
 		}

 		++index;
 	} while (phy_cfgs[index].reg);

 	if (!rphy->phy_cfg) {
 		dev_err(dev, "could not find phy config for reg=0x%08x\n", reg);
 		return -EINVAL;
 	}

 	rphy->phy_reset = devm_reset_control_get_optional(dev, "phy");
 	if (IS_ERR(rphy->phy_reset))
 		return PTR_ERR(rphy->phy_reset);

 	ret = devm_clk_bulk_get_all(dev, &rphy->clks);
 	if (ret == -EPROBE_DEFER)
 		return dev_err_probe(&pdev->dev, -EPROBE_DEFER,
 				     "failed to get phy clock\n");

 	/* Clocks are optional */
 	rphy->num_clks = ret < 0 ? 0 : ret;

 	ret = rockchip_usb2phy_clk480m_register(rphy);
 	if (ret)
 		return dev_err_probe(dev, ret, "failed to register 480m output clock\n");

 	ret = clk_bulk_prepare_enable(rphy->num_clks, rphy->clks);
 	if (ret)
 		return dev_err_probe(dev, ret, "failed to enable phy clock\n");

 	ret = devm_add_action_or_reset(dev, rockchip_usb2phy_clk_bulk_disable, rphy);
 	if (ret)
 		return ret;

 	if (rphy->phy_cfg->phy_tuning) {
 		ret = rphy->phy_cfg->phy_tuning(rphy);
 		if (ret)
 			return ret;
 	}

 	index = 0;
 	for_each_available_child_of_node(np, child_np) {
 		struct rockchip_usb2phy_port *rport = &rphy->ports[index];
 		struct phy *phy;

 		/* This driver aims to support both otg-port and host-port */
 		if (!of_node_name_eq(child_np, "host-port") &&
 		    !of_node_name_eq(child_np, "otg-port"))
 			goto next_child;

 		phy = devm_phy_create(dev, child_np, &rockchip_usb2phy_ops);
 		if (IS_ERR(phy)) {
 			ret = dev_err_probe(dev, PTR_ERR(phy), "failed to create phy\n");
 			goto put_child;
 		}

 		rport->phy = phy;
 		phy_set_drvdata(rport->phy, rport);

 		/* initialize otg/host port separately */
 		if (of_node_name_eq(child_np, "host-port")) {
 			ret = rockchip_usb2phy_host_port_init(rphy, rport, child_np);
 			if (ret)
 				goto put_child;
 		} else {
 			ret = rockchip_usb2phy_otg_port_init(rphy, rport, child_np);
 			if (ret)
 				goto put_child;
 		}

 next_child:
 		/* to prevent out of boundary */
 		if (++index >= rphy->phy_cfg->num_ports) {
 			of_node_put(child_np);
 			break;
 		}
 	}

 	provider = devm_of_phy_provider_register(dev, of_phy_simple_xlate);

 	if (rphy->irq > 0) {
 		ret = devm_request_threaded_irq(rphy->dev, rphy->irq, NULL,
 						rockchip_usb2phy_irq,
 						IRQF_ONESHOT,
 						"rockchip_usb2phy",
 						rphy);
 		if (ret) {
 			dev_err_probe(rphy->dev, ret, "failed to request usb2phy irq handle\n");
-			goto put_child;
+			return ret;
 		}
 	}

 	return PTR_ERR_OR_ZERO(provider);

 put_child:
 	of_node_put(child_np);
 	return ret;
 }

